-- STEP 2: upsert
begin;

on conflict (pile_no) do update set
  zone = excluded.zone,
  dia_mm = excluded.dia_mm,
  pile_top_level = excluded.pile_top_level,
  sea_bed_level = excluded.sea_bed_level,
  pile_toe_level = excluded.pile_toe_level,
  length_m = excluded.length_m,
  incline = excluded.incline,
  coordinate_pn = excluded.coordinate_pn,
  coordinate_pe = excluded.coordinate_pe,
  coating_length_m = excluded.coating_length_m,
  batter_bearing_deg = excluded.batter_bearing_deg,
  note = excluded.note
returning pile_no, zone, coordinate_pn, coordinate_pe, batter_bearing_deg;

commit;

